// nomes com "de/do" usados nas regras
const day = { amanhã: 'tomorrow', segunda: 'Monday', terça: 'Tuesday', quarta: 'Wednesday', quinta: 'Thursday', sexta: 'Friday' };
const list = (s, t) => s.split(/, | e /).map((x) => t(x)).join(', ').replace(/, ([^,]+)$/, ' and $1');

const patterns = [
  [/^(.+) \| AlquiVerde$/, (m, t, s) => (s(m[1]) ? `${s(m[1])} | Alquiverde` : null)],
  [/^(.+)\. Veja os itens, as opções de embalagem e os cuidados de uso\.$/, (m, t, s) => (s(m[1]) ? `${s(m[1])}. See the items, packaging options and care instructions.` : null)],
  [/^De R\$ ([\d.,]+) por R\$ ([\d.,]+) \((\d+)% de desconto\)$/, (m) => `Was R$ ${m[1]}, now R$ ${m[2]} (${m[3]}% off)`],
  [/^R\$ [\d.,]+$/, (m) => m[0]],
  [/^[\d.,]+ ?(?:g|mL|ml|cm|h|min)$/, (m) => m[0]],
  [/^(\d+) de (\d+) · faltam (\d+)$/, (m) => `${m[1]} of ${m[2]} · ${m[3]} to go`],
  [/^(\d+) de (\d+) · caixa completa$/, (m) => `${m[1]} of ${m[2]} · box complete`],
  [/^(\d+)\/(\d+) sabonetes(?: · (\d+) extras?)?$/, (m) => `${m[1]}/${m[2]} soaps${m[3] ? ` · ${m[3]} extra${m[3] > 1 ? 's' : ''}` : ''}`],
  [/^opcional · até (\d+)$/, (m) => `optional · up to ${m[1]}`],
  [/^\+ até (\d+) extras$/, (m) => `+ up to ${m[1]} extras`],
  [/^Caixa de presente para (\d+) sabonetes$/, (m) => `Gift box for ${m[1]} soaps`],
  [/^Faltam (\d+) sabonetes?$/, (m) => `${m[1]} soap${m[1] > 1 ? 's' : ''} to go`],
  [/^(\d+) itens, um por um\. (.+)$/, (m, t) => `${m[1]} item${m[1] > 1 ? 's' : ''}, one by one. ${t(m[2])}`],
  [/^(\d+) sabonetes · (\d+) g no total\. (.+)$/, (m, t) => `${m[1]} soaps · ${m[2]} g in total. ${t(m[3])}`],
  [/^(\d+) ×$/, (m) => m[0]],
  [/^(\d+) × (.+)$/, (m, t) => `${m[1]} × ${t(m[2])}`],
  [/^Caixa aberta do (.+)$/, (m, t) => `Open box of the ${t(m[1])}`],
  [/^Conhecer (.+)$/, (m, t, s) => (s(m[1]) ? `Discover ${s(m[1])}` : null)],
  [/^(.+) em 3D\. Arraste ou use as setas para girar\.$/, (m, t) => `${t(m[1])} in 3D. Drag or use the arrow keys to rotate.`],
  [/^Pôr um sabonete de (.+)$/, (m, t) => `Add one ${t(m[1])} soap`],
  [/^Tirar um sabonete de (.+)$/, (m, t) => `Remove one ${t(m[1])} soap`],
  [/^Sabonetes de (.+) na caixa$/, (m, t) => `${t(m[1])} soaps in the box`],
  [/^Combinação do (.+)$/, (m, t) => `${t(m[1])} combination`],
  [/^Vem no (.+)$/, (m, t) => `Comes in the ${list(m[1], t)}`],
  [/^Vem na combinação (.+)$/, (m, t) => `Comes in the ${m[1].split(' e ').map(t).join(' and ')} combination`],
  [/^Sabonetes? [Vv]egeta(?:l|is) de (.+)$/, (m, t, s) => (s(m[1]) ? `${s(m[1])} plant-based soap${/^Sabonetes/.test(m[0]) ? 's' : ''}` : null)],
  [/^Sabonete vegetal (.+) 90 g$/, (m, t, s) => (s(m[1]) ? `${s(m[1])} plant-based soap, 90 g` : null)],
  [/^Óleo Essencial de (.+?)( 10 mL)?$/, (m, t, s) => (s(m[1]) ? `${s(m[1])} Essential Oil${m[2] || ''}` : null)],
  [/^Obrigada, (.+)!$/, (m) => `Thank you, ${m[1]}!`],
  [/^Pedido de proposta para (.+) presentes enviado\. A equipe responde no seu e-mail em até 1 dia útil\.$/, (m, t) => {
    const q = t(m[1].charAt(0).toUpperCase() + m[1].slice(1)).toLowerCase();
    return `Quote request for ${q} gifts sent. Our team will reply to your email within 1 business day.`;
  }],
  [/^Peça nas próximas (.+) e receba hoje$/, (m) => `Order within the next ${m[1]} to get it today`],
  [/^Próxima entrega no mesmo dia: (\S+), pedidos até 12h$/, (m) => `Next same-day delivery: ${day[m[1]] || m[1]}, orders by 12 p.m.`],
  [/^Kit (\d+) de (\d+): (.+)$/, (m, t) => `Kit ${m[1]} of ${m[2]}: ${t(m[3])}`],
  [/^Kit Monte o seu · (\d+) sabonetes$/, (m) => `Build-your-own kit · ${m[1]} soaps`],
  [/^\+ (.+)$/, (m, t) => `+ ${m[1].split(', ').map(t).join(', ')}`],
  [/^(.+?) \+ (\D.*)$/, (m, t) => `${t(m[1])} + ${m[2].split(', ').map(t).join(', ')}`],
  [/^(\d+) (\p{L}.*)$/u, (m, t, s) => (s(m[2]) ? `${m[1]} ${s(m[2])}` : null)],
  // "Nome: descrição. Presente nos kits A, B." (cards de ingredientes)
  [/^(.+?): (.+?) Presente nos kits (.+)\.$/, (m, t) => `${t(m[1])}: ${t(m[2])} In the kits ${m[3].split(', ').map(t).join(', ')}.`],
  // "Kit: combinação" e outros rótulos com dois-pontos
  [/^([^:]+): (.+)$/, (m, t, s) => (s(m[1]) && s(m[2]) ? `${s(m[1])}: ${s(m[2])}` : null)],
];

export default { text: { ...NAMES, ...TEXT }, patterns };
